class Solution {
public:
    int countCoprime(vector<vector<int>>& mat) {
        const int LIM = 151, MOD = 1e9 + 7;
        vector<int> mu(LIM, 1), comp(LIM, 0);
        vector<int> primes;
        for (int i = 2; i < LIM; i++) {
            if (!comp[i]) { primes.push_back(i); mu[i] = -1; }
            for (int p : primes) {
                if ((long long)i * p >= LIM) break;
                comp[i*p] = 1;
                if (i % p == 0) { mu[i*p] = 0; break; }
                mu[i*p] = -mu[i];
            }
        }
        long long ans = 0;
        for (int d = 1; d < LIM; d++) {
            if (!mu[d]) continue;
            long long prod = 1;
            for (auto& row : mat) {
                long long c = 0;
                for (int x : row) if (x % d == 0) c++;
                prod = prod * (c % MOD) % MOD;
            }
            ans = (ans + mu[d] * prod % MOD + MOD) % MOD;
        }
        return (int)ans;
    }
};

