class Solution:
    def countCoprime(self, mat: list[list[int]]) -> int:
        MOD = 10 ** 9 + 7
        T = [1] * 151
        for d in range(1, 151):
            for row in mat:
                T[d] = T[d] * sum(1 for x in row if x % d == 0) % MOD
        exact = [0] * 151
        for g in range(150, 0, -1):
            val = T[g]
            for k in range(2 * g, 151, g):
                val -= exact[k]
            exact[g] = val % MOD
        return exact[1] % MOD

