class Solution {
public:
    int countCoprime(vector<vector<int>>& mat) {
        const int MOD = 1e9 + 7;
        vector<long long> T(151, 1), ex(151, 0);
        for (int d = 1; d <= 150; d++)
            for (auto& row : mat) {
                long long c = 0;
                for (int x : row) if (x % d == 0) c++;
                T[d] = T[d] * (c % MOD) % MOD;
            }
        for (int g = 150; g >= 1; g--) {
            long long v = T[g];
            for (int k = 2 * g; k <= 150; k += g) v -= ex[k];
            ex[g] = ((v % MOD) + MOD) % MOD;
        }
        return (int)ex[1];
    }
};

